package com.studentgig.controller; import com.studentgig.model.Message; import com.studentgig.repository.MessageRepository; import org.springframework.web.bind.annotation.*; import jakarta.servlet.http.*; import java.util.*;
@RestController @RequestMapping("/api/messages") public class MessageController {final MessageRepository r;MessageController(MessageRepository r){this.r=r;}@GetMapping public Object inbox(HttpSession s){Object id=s.getAttribute("userId");return id==null?List.of():r.findByReceiverIdOrderBySentAtDesc((Long)id);}@PostMapping public Object send(@RequestBody Message m,HttpSession s){Object id=s.getAttribute("userId");if(id==null)return Map.of("error","Please login");m.senderId=(Long)id;return r.save(m);}@PutMapping("/{id}/read")public Object read(@PathVariable Long id){Message m=r.findById(id).orElseThrow();m.readFlag=true;return r.save(m);}}
